const state = await appStore.getState();
const baseState = state && typeof state === "object" ? state : {};

const todos = Array.isArray(baseState.todos) ? baseState.todos : [];

const els = {
  form: document.querySelector('[data-role="add-form"]'),
  input: document.querySelector('[data-role="task-input"]'),
  hint: document.querySelector('[data-role="form-hint"]'),
  list: document.querySelector('[data-role="todo-list"]'),
  emptyTip: document.querySelector('[data-role="empty-tip"]'),
  statDone: document.querySelector('[data-role="stat-done"]'),
  statTotal: document.querySelector('[data-role="stat-total"]'),
  listCount: document.querySelector('[data-role="list-count"]'),
  mask: document.querySelector('[data-role="dialog-mask"]'),
  dialogText: document.querySelector('[data-role="dialog-text"]'),
  dialogCancel: document.querySelector('[data-role="dialog-cancel"]'),
  dialogConfirm: document.querySelector('[data-role="dialog-confirm"]')
};

function makeId() {
  return "t-" + Date.now().toString(36) + "-" + Math.random().toString(36).slice(2, 8);
}

function normalizeTodo(raw) {
  const item = raw && typeof raw === "object" ? raw : {};
  return {
    ...item,
    id: typeof item.id === "string" && item.id ? item.id : makeId(),
    text: typeof item.text === "string" ? item.text : String(item.text == null ? "" : item.text),
    done: item.done === true
  };
}

function render() {
  const total = todos.length;
  const doneCount = todos.filter(function (t) { return t.done === true; }).length;

  els.statDone.textContent = String(doneCount);
  els.statTotal.textContent = String(total);
  els.listCount.textContent = "共 " + total + " 项";

  els.list.textContent = "";
  todos.forEach(function (todo) {
    const li = document.createElement("li");
    li.className = "todo-item" + (todo.done ? " is-done" : "");
    li.dataset.todoId = todo.id;

    const checkbox = document.createElement("input");
    checkbox.type = "checkbox";
    checkbox.className = "todo-check";
    checkbox.checked = todo.done === true;
    checkbox.dataset.role = "toggle";
    checkbox.setAttribute("aria-label", "标记完成：" + todo.text);

    const span = document.createElement("span");
    span.className = "todo-text";
    span.textContent = todo.text;

    const del = document.createElement("button");
    del.type = "button";
    del.className = "todo-delete";
    del.dataset.role = "delete";
    del.textContent = "删除";

    li.appendChild(checkbox);
    li.appendChild(span);
    li.appendChild(del);
    els.list.appendChild(li);
  });

  els.emptyTip.hidden = total > 0;
}

async function persist(nextTodos) {
  const next = Object.assign({}, baseState, { todos: nextTodos });
  await appStore.setState(next);
  const check = await appStore.getState();
  const saved = check && Array.isArray(check.todos) ? check.todos : [];
  todos.length = 0;
  saved.forEach(function (t) { todos.push(normalizeTodo(t)); });
  render();
}

function showHint(msg) {
  els.hint.textContent = msg;
}

function openConfirm(text) {
  return new Promise(function (resolve) {
    els.dialogText.textContent = text;
    els.mask.hidden = false;

    function cleanup() {
      els.mask.hidden = true;
      els.dialogConfirm.removeEventListener("click", onConfirm);
      els.dialogCancel.removeEventListener("click", onCancel);
      els.mask.removeEventListener("click", onMaskClick);
      document.removeEventListener("keydown", onKey);
    }
    function onConfirm() { cleanup(); resolve(true); }
    function onCancel() { cleanup(); resolve(false); }
    function onMaskClick(e) { if (e.target === els.mask) { cleanup(); resolve(false); } }
    function onKey(e) { if (e.key === "Escape") { cleanup(); resolve(false); } }

    els.dialogConfirm.addEventListener("click", onConfirm);
    els.dialogCancel.addEventListener("click", onCancel);
    els.mask.addEventListener("click", onMaskClick);
    document.addEventListener("keydown", onKey);
    els.dialogConfirm.focus();
  });
}

els.form.addEventListener("submit", async function (e) {
  e.preventDefault();
  const text = els.input.value.trim();
  if (!text) {
    showHint("请输入任务名称后再添加。");
    els.input.focus();
    return;
  }
  showHint("");
  const nextTodos = todos.map(function (t) { return Object.assign({}, t); });
  nextTodos.push({ id: makeId(), text: text, done: false });
  try {
    await persist(nextTodos);
    els.input.value = "";
    els.input.focus();
  } catch (err) {
    showHint("保存失败，请重试。");
  }
});

els.list.addEventListener("change", async function (e) {
  const target = e.target;
  if (!target || target.dataset.role !== "toggle") return;
  const li = target.closest(".todo-item");
  if (!li) return;
  const id = li.dataset.todoId;
  const nextTodos = todos.map(function (t) {
    if (t.id === id) {
      return Object.assign({}, t, { done: target.checked === true });
    }
    return Object.assign({}, t);
  });
  try {
    await persist(nextTodos);
  } catch (err) {
    showHint("保存失败，请重试。");
    render();
  }
});

els.list.addEventListener("click", async function (e) {
  const target = e.target;
  if (!target || target.dataset.role !== "delete") return;
  const li = target.closest(".todo-item");
  if (!li) return;
  const id = li.dataset.todoId;
  const targetTodo = todos.filter(function (t) { return t.id === id; })[0];
  if (!targetTodo) return;

  const confirmed = await openConfirm("确定要删除任务「" + targetTodo.text + "」吗？此操作无法撤销。");
  if (!confirmed) return;

  const nextTodos = todos
    .filter(function (t) { return t.id !== id; })
    .map(function (t) { return Object.assign({}, t); });
  try {
    await persist(nextTodos);
  } catch (err) {
    showHint("保存失败，请重试。");
  }
});

render();

