:root {
  --bg: #0f172a;
  --bg-soft: #16213c;
  --panel: #1c2946;
  --panel-2: #22304f;
  --border: #33436b;
  --text: #eef2ff;
  --text-dim: #a3b0d0;
  --accent: #5b8cff;
  --accent-strong: #3f6fe8;
  --danger: #ef5f6b;
  --danger-strong: #d8434f;
  --ok: #4ecb8d;
}

#app {
  min-height: 100vh;
  background: radial-gradient(circle at 15% 0%, #1d2b4d 0%, var(--bg) 55%, #0a1020 100%);
  color: var(--text);
  font-family: "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", system-ui, -apple-system, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

#app *,
#app *::before,
#app *::after {
  box-sizing: border-box;
}

.app-shell {
  max-width: 640px;
  margin: 0 auto;
  padding: 28px 16px 56px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.app-header {
  padding: 4px 2px 0;
}

.app-title {
  margin: 0;
  font-size: 26px;
  font-weight: 700;
  letter-spacing: 0.5px;
  color: var(--text);
}

.app-subtitle {
  margin: 6px 0 0;
  font-size: 14px;
  color: var(--text-dim);
}

.panel {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 16px;
  box-shadow: 0 10px 24px rgba(4, 9, 22, 0.35);
}

.field-label {
  display: block;
  font-size: 13px;
  font-weight: 600;
  color: var(--text-dim);
  margin-bottom: 8px;
}

.add-row {
  display: flex;
  gap: 10px;
}

.task-input {
  flex: 1 1 auto;
  min-width: 0;
  padding: 12px 14px;
  font-size: 16px;
  color: var(--text);
  background: var(--bg-soft);
  border: 1px solid var(--border);
  border-radius: 10px;
  outline: none;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.task-input::placeholder {
  color: #7c8ab0;
}

.task-input:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(91, 140, 255, 0.22);
}

.btn {
  font-family: inherit;
  font-size: 15px;
  font-weight: 600;
  border-radius: 10px;
  border: 1px solid transparent;
  padding: 12px 18px;
  cursor: pointer;
  transition: background 0.15s ease, border-color 0.15s ease, color 0.15s ease;
}

.btn-primary {
  background: var(--accent);
  color: #ffffff;
  white-space: nowrap;
}

.btn-primary:hover {
  background: var(--accent-strong);
}

.btn-ghost {
  background: transparent;
  color: var(--text-dim);
  border-color: var(--border);
}

.btn-ghost:hover {
  color: var(--text);
  border-color: var(--accent);
}

.btn-danger {
  background: var(--danger);
  color: #ffffff;
}

.btn-danger:hover {
  background: var(--danger-strong);
}

.form-hint {
  margin: 10px 0 0;
  min-height: 18px;
  font-size: 13px;
  color: var(--danger);
}

.stats-panel {
  display: flex;
  align-items: center;
  justify-content: space-around;
  padding: 14px 16px;
}

.stat {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  flex: 1 1 0;
}

.stat-value {
  font-size: 24px;
  font-weight: 700;
  color: var(--ok);
}

.stat-label {
  font-size: 13px;
  color: var(--text-dim);
}

.stat-divider {
  width: 1px;
  align-self: stretch;
  background: var(--border);
}

.list-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 10px;
}

.list-title {
  margin: 0;
  font-size: 16px;
  font-weight: 700;
  color: var(--text);
}

.list-count {
  font-size: 13px;
  color: var(--text-dim);
}

.todo-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.todo-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px;
  background: var(--panel-2);
  border: 1px solid var(--border);
  border-radius: 10px;
}

.todo-item.is-done {
  border-color: rgba(78, 203, 141, 0.45);
}

.todo-check {
  flex: 0 0 auto;
  width: 22px;
  height: 22px;
  accent-color: var(--ok);
  cursor: pointer;
}

.todo-text {
  flex: 1 1 auto;
  min-width: 0;
  font-size: 15px;
  color: var(--text);
  word-break: break-word;
}

.todo-item.is-done .todo-text {
  color: var(--text-dim);
  text-decoration: line-through;
}

.todo-delete {
  flex: 0 0 auto;
  font-family: inherit;
  font-size: 13px;
  font-weight: 600;
  color: var(--danger);
  background: transparent;
  border: 1px solid rgba(239, 95, 107, 0.5);
  border-radius: 8px;
  padding: 6px 10px;
  cursor: pointer;
}

.todo-delete:hover {
  background: rgba(239, 95, 107, 0.14);
}

.empty-tip {
  margin: 4px 0 0;
  font-size: 14px;
  color: var(--text-dim);
  text-align: center;
  padding: 14px 0;
}

.dialog-mask {
  position: fixed;
  inset: 0;
  background: rgba(6, 11, 24, 0.72);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  z-index: 50;
}

.dialog-mask[hidden] {
  display: none;
}

.dialog {
  width: 100%;
  max-width: 360px;
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 14px;
  padding: 20px;
  box-shadow: 0 18px 40px rgba(3, 7, 18, 0.55);
}

.dialog-title {
  margin: 0 0 8px;
  font-size: 17px;
  color: var(--text);
}

.dialog-text {
  margin: 0 0 18px;
  font-size: 14px;
  color: var(--text-dim);
  word-break: break-word;
}

.dialog-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
}

@media (max-width: 420px) {
  .app-shell {
    padding: 20px 12px 44px;
  }

  .add-row {
    flex-direction: column;
  }

  .btn-primary {
    width: 100%;
  }

  .app-title {
    font-size: 22px;
  }
}
